Ces objets sont des bandeaux, des rubans, des phylact&#232;res et tous les objets port&#233;s sur le front.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; sur le front &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0 g et 500 g.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur le front&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Contr&#244;le-De-La-Vermine.html&quot; title=&quot;Bandeau de contr&#244;le de la vermine&quot;&gt;Bandeau de contr&#244;le de la vermine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Harmonis&#233; au porteur (10 minutes de port), permet de tenter des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; pour influencer le comportement de &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vermine.html&quot; title=&quot;Vermine&quot;&gt;vermines&lt;/a&gt; comme si elles poss&#233;daient une intelligence animale.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phylact&#232;re-Du-Croyant.html&quot; title=&quot;Phylact&#232;re du croyant&quot;&gt;Phylact&#232;re du croyant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pr&#233;vient un croyant qu’un acte qu’il commet est contre l’alignement de sa divinit&#233;.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Du-Mort.html&quot; title=&quot;Bandeau du mort&quot;&gt;Bandeau du mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; et augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des effets de terreur de 1. Conf&#232;re un bonus de circonstance +5 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; du couvre-chef auquel il est attach&#233; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#SUBTILISATION&quot; title=&quot;Les manœuvres offensives&quot;&gt;subtilisation&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESTRUCTION&quot; title=&quot;Les manœuvres offensives&quot;&gt;destruction&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Belle-Allure.html&quot; title=&quot;Bandeau de belle allure&quot;&gt;Bandeau de belle allure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration au &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dinspiration.html&quot; title=&quot;Bandeau d&amp;#39;inspiration&quot;&gt;Bandeau d’inspiration&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dintelligence.html&quot; title=&quot;Bandeau d&amp;#39;intelligence&quot;&gt;Bandeau d’intelligence&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dagilit&#233;-A&#233;rienne.html&quot; title=&quot;Bandeau d’agilit&#233; a&#233;rienne&quot;&gt;Bandeau d’agilit&#233; a&#233;rienne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la valeur d’une caract&#233;ristique mentale (temporaire pendant les 24 premi&#232;res heures de port) choisie &#224; la fabrication, ainsi que des effets suppl&#233;mentaires cumulatifs.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2. Augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; de +1 pour les sorts/extraits qui permettent de voler.&lt;/td&gt;&lt;td&gt;4 500 p&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4. M&#234;me effet que le &lt;i&gt;Bandeau +2&lt;/i&gt;. Trois fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;| 42 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6. M&#234;mes effets que le &lt;i&gt;Bandeau +4&lt;/i&gt;, mais permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;| 81 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-M&#233;tamorphe.html&quot; title=&quot;Bandeau de m&#233;tamorphe&quot;&gt;Bandeau de m&#233;tamorphe&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la valeur d’une caract&#233;ristique mentale (temporaire pendant les 24 premi&#232;res heures de port) choisie &#224; la fabrication, ainsi que des effets suppl&#233;mentaires cumulatifs.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2. Augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; de +1 pour les sorts/extraits qui permettent de se m&#233;tamorphoser.&lt;/td&gt;&lt;td&gt;4 500 p&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4. M&#234;me effet que le &lt;i&gt;Bandeau +2&lt;/i&gt;. Une fois par jour, permet de changer les effets d’un sort de m&#233;tamorphose actif.&lt;/td&gt;&lt;td&gt;| 17 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6. M&#234;mes effets que le &lt;i&gt;Bandeau +4&lt;/i&gt;. Tant que le porteur est soumit &#224; un effet de m&#233;tamorphose, conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/argent pendant 1 minute.&lt;/td&gt;&lt;td&gt;| 39 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Du-Loup.html&quot; title=&quot;Bandeau du loup&quot;&gt;Bandeau du loup&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;Odorat (Ext)&quot;&gt;odorat&lt;/a&gt; (3m), &#224; volont&#233;. Un &lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html&quot; title=&quot;Le chasseur&quot;&gt;chasseur&lt;/a&gt; qui poss&#232;de l’&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html#IMITATIONANIMALE&quot; title=&quot;Le chasseur&quot;&gt;aspect du loup&lt;/a&gt; voit son niveau effectif augmenter de 8 pour en d&#233;terminer les effets &#224; la place.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-R&#233;miniscence.html&quot; title=&quot;Bandeau de r&#233;miniscence&quot;&gt;Bandeau de r&#233;miniscence&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port). Trois fois par jour, permet d’apprendre les aptitudes/faiblesses d’une cr&#233;ature, comme avec un test de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Focalisation-Ki.html&quot; title=&quot;Bandeau de focalisation ki&quot;&gt;Bandeau de focalisation ki&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les attaques suppl&#233;mentaires octroy&#233;es par la d&#233;pense de points de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;ki&lt;/a&gt; b&#233;n&#233;ficient d’un bonus d’intuition de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; (+2 avec une arme &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Focalisation-Ki.html&quot; title=&quot;focalisation ki (propri&#233;t&#233;)&quot;&gt;de focalisation ki&lt;/a&gt;). Immunise contre l’incapacit&#233; &#224; utiliser le &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;ki&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-R&#233;solution-In&#233;branlable.html&quot; title=&quot;Bandeau de r&#233;solution in&#233;branlable&quot;&gt;Bandeau de r&#233;solution in&#233;branlable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; (temporaire les 24 premi&#232;res heures de port). Trois fois par jour, permet de r&#233;duire l’&#233;tat inflig&#233; par un effet de terreur d’un cran.&lt;/td&gt;&lt;td&gt;5 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couronne-De-Houx.html&quot; title=&quot;Couronne de houx&quot;&gt;Couronne de houx&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; de 1 pour tous les effets affectant les plantes. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baie-Nourrici&#232;re.html&quot; title=&quot;Baie nourrici&#232;re&quot;&gt;baie nourrici&#232;re&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;5 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dinfaillible-D&#233;termination.html&quot; title=&quot;Bandeau d’infaillible d&#233;termination&quot;&gt;Bandeau d’infaillible d&#233;termination&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#STABLE&quot; title=&quot;Blessures et mort&quot;&gt;tests de stabilisation&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; r&#233;currents contre un m&#234;me effet. Un &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html&quot; title=&quot;Le samoura&#239;&quot;&gt;samoura&#239;&lt;/a&gt; voit son niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html&quot; title=&quot;Le samoura&#239;&quot;&gt;samoura&#239;&lt;/a&gt; augment&#233; de 2 pour d&#233;terminer les effets de sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html#RESOLUTION&quot; title=&quot;Le samoura&#239;&quot;&gt;r&#233;solution&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;6 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dintuition.html&quot; title=&quot;Bandeau d’intuition&quot;&gt;Bandeau d’intuition&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut apprendre des informations sur un Plan sp&#233;cifique (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augure.html&quot; title=&quot;Augure&quot;&gt;augure&lt;/a&gt;&lt;/i&gt;, mais donne toujours une r&#233;ponse significative).&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phylact&#232;re-Du-Berger.html&quot; title=&quot;Phylact&#232;re du berger&quot;&gt;Phylact&#232;re du berger&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapport.html&quot; title=&quot;Rapport&quot;&gt;rapport&lt;/a&gt;&lt;/i&gt; sur une cr&#233;ature &#224; 9 m ou moins. Le porteur peut mettre fin &#224; l’effet pour utiliser une &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisation d’&#233;nergie&lt;/a&gt; ou une &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; sur sa cible (toujours &#224; 9 m ou moins).&lt;/td&gt;&lt;td&gt;7 000 po &lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Chance-Renforc&#233;e.html&quot; title=&quot;Bandeau de chance renforc&#233;e&quot;&gt;Bandeau de chance renforc&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de chance de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;. Tous les effets avec une dur&#233;e affectant la chance durent 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; suppl&#233;mentaire.&lt;/td&gt;&lt;td&gt;7 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Lenrag&#233;.html&quot; title=&quot;Bandeau de l’enrag&#233;&quot;&gt;Bandeau de l’enrag&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; voit son niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; augment&#233; de 4 pour un &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#POUVOIRDERAGE&quot; title=&quot;Le barbare&quot;&gt;pouvoir de rage&lt;/a&gt; au choix, chaque fois qu’il entre en &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt;. Une fois par jour, permet de d&#233;penser 2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; pour entrer dans cet &#233;tat par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; au moment o&#249; une attaque le cible.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Du-Serpent.html&quot; title=&quot;Bandeau du serpent&quot;&gt;Bandeau du serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’intuition de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets du registre des &#233;motions (effets de terreur compris). Permet de parler le draconique et de converser avec les cr&#233;atures magiques de type reptilien d&#233;nu&#233;s d’intelligence (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Animaux.html&quot; title=&quot;Communication avec les animaux&quot;&gt;communication avec les animaux&lt;/a&gt;&lt;/i&gt;). Conf&#232;re un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt; sur ces cr&#233;atures.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Prouesse-Mentale.html&quot; title=&quot;Bandeau de prouesse mentale&quot;&gt;Bandeau de prouesse mentale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la valeur de deux caract&#233;ristiques mentales (temporaire pendant les 24 premi&#232;res heures de port) choisies &#224; la fabrication.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;10 000 p&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 90 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Du-Chasseur.html&quot; title=&quot;Bandeau du chasseur&quot;&gt;Bandeau du chasseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;, et les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Infatigable-Poursuivant.html&quot; title=&quot;Infatigable poursuivant&quot;&gt;infatigable poursuivant&lt;/a&gt;&lt;/i&gt; en permanence. Un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; augmente le bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; de sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemi jur&#233;&lt;/a&gt; de +1 (cette augmentation s’applique &#224; son compagnon s’il a choisi le &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#PACTEDUCHASSEUR&quot; title=&quot;Le r&#244;deur&quot;&gt;pacte du chasseur&lt;/a&gt; (compagnon)).&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phylact&#232;re-De-Canalisation.html&quot; title=&quot;Phylact&#232;re de canalisation&quot;&gt;Phylact&#232;re de canalisation d’&#233;nergie n&#233;gative&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Augmente les soins/d&#233;g&#226;ts de la &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisation d’&#233;nergie&lt;/a&gt; n&#233;gative de 2d6.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phylact&#232;re-De-Canalisation.html&quot; title=&quot;Phylact&#232;re de canalisation&quot;&gt;Phylact&#232;re de canalisation d’&#233;nergie positive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Augmente les soins/d&#233;g&#226;ts de la &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisation d’&#233;nergie&lt;/a&gt; positive de 2d6.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Œil-Voil&#233;.html&quot; title=&quot;Œil voil&#233;&quot;&gt;Œil voil&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Poss&#232;de la m&#234;me vision que son porteur. Si ce denier ne peut plus se servir de ses yeux, il peut voir par cet œil normalement. Lorsque le porteur utilise cet œil, il subit un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; &#224; distance mais obtient un bonus d’intuition de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les attaques de regard.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Vaillance.html&quot; title=&quot;Bandeau de vaillance&quot;&gt;Bandeau de vaillance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre les effets de terreur. Si le porteur poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#COURAGE&quot; title=&quot;Le guerrier&quot;&gt;courage&lt;/a&gt;, son niveau de classe est augment&#233; de 4 d&#233;terminer ses effets. Les effets de terreur ne peuvent pas rendre le porteur plus que &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Secou&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;secou&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Ninjitsu.html&quot; title=&quot;Bandeau de ninjitsu&quot;&gt;Bandeau de ninjitsu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; pour &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#FEINTE&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;feinter&lt;/a&gt;, aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#REPOSITIONNEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;repositionnement&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; des attaques sournoises. Une fois par jour, il peut tenter une de ces deux actions par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Permet d&#39;infliger des attaques sournoises m&#234;me aux cr&#233;atures qui b&#233;n&#233;ficient d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat.html#CAMOUFLAGE&quot; title=&quot;Modificateurs de combat&quot;&gt;camouflage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Sup&#233;riorit&#233;-Mentale.html&quot; title=&quot;Bandeau de sup&#233;riorit&#233; mentale&quot;&gt;Bandeau de sup&#233;riorit&#233; mentale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; la valeur de toutes les caract&#233;ristiques mentales (temporaire pendant les 24 premi&#232;res heures de port).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +6.&lt;/td&gt;&lt;td&gt;| 144 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-De-Cin&#233;tiste.html&quot; title=&quot;Diad&#232;me de cin&#233;tiste&quot;&gt;Diad&#232;me de cin&#233;tiste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Augmente les d&#233;g&#226;ts des &lt;a class=&quot;pagelink&quot; href=&quot;Talents-Sauvages.html#EXPLOSIONSSIMPLES&quot; title=&quot;Les talents sauvages du cin&#233;tiste&quot;&gt;explosions simples&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Talents-Sauvages.html#EXPLOSIONSCOMPOSITES&quot; title=&quot;Les talents sauvages du cin&#233;tiste&quot;&gt;composites&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Cin&#233;tiste.html&quot; title=&quot;Le cin&#233;tiste&quot;&gt;cin&#233;tiste&lt;/a&gt;. Les d&#233;s des explosions physiques deviennent des d8. Ces d&#233;g&#226;ts suppl&#233;mentaires sont multipli&#233;s en cas de coup critique, mais ne s’appliquent pas aux explosions associ&#233;es &#224; des injections de forme interdisant le bonus du &lt;a class=&quot;pagelink&quot; href=&quot;Cin&#233;tiste.html#BOUILLONNEMENT&#201;L&#201;MENTAIRE&quot; title=&quot;Le cin&#233;tiste&quot;&gt;bouillonnement &#233;l&#233;mentaire&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;L’augmentation est de 1d6.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; normal&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;L’augmentation est de 2d6.&lt;/td&gt;&lt;td&gt;| 50 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;L’augmentation est de 3d6.&lt;/td&gt;&lt;td&gt;| 98 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-D&#233;nergie-Magique.html&quot; title=&quot;Bandeau d’&#233;nergie magique&quot;&gt;Bandeau d’&#233;nergie magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de sacrifier un sort profane pour produire une explosion (attaque de contact &#224; distance, 9 m, 1d6 d&#233;g&#226;ts d’&#233;nergie d&#233;pendant du sort sacrifi&#233;) ou un bouclier (bonus de parade de +2(+ niveau du sort sacrifi&#233;) &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Contresort.html&quot; title=&quot;Bandeau de contresort&quot;&gt;Bandeau de contresort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’intuition de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; pour identifier un sort en train d’&#234;tre lanc&#233;. Une fois par jour, permet de contrer un sort identifi&#233; avec le m&#234;me sort par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-De-La-Lune.html&quot; title=&quot;Diad&#232;me de la lune&quot;&gt;Diad&#232;me de la lune&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re la &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#VISIONDANSLENOIR&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;vision dans le noir&lt;/a&gt; (18m) en permanence. Renforce la magie du porteur en fonction de la phase actuelle de la lune.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Ma&#238;trise-Des-Zombis.html&quot; title=&quot;Bandeau de ma&#238;trise des zombis&quot;&gt;Bandeau de ma&#238;trise des zombis&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Mineur-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le mineur des morts-vivants&quot;&gt;contr&#244;le mineur des morts-vivants&lt;/a&gt;&lt;/i&gt; uniquement sur les &lt;a class=&quot;pagelink&quot; href=&quot;Zombi,-Arch&#233;type.html&quot; title=&quot;Zombi, arch&#233;type&quot;&gt;zombis&lt;/a&gt;. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animation-Des-Morts.html&quot; title=&quot;Animation des morts&quot;&gt;animation des morts&lt;/a&gt;&lt;/i&gt; sur un &lt;a class=&quot;pagelink&quot; href=&quot;Zombi,-Arch&#233;type.html&quot; title=&quot;Zombi, arch&#233;type&quot;&gt;zombi&lt;/a&gt; de taille M.&lt;/td&gt;&lt;td&gt;27 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Œil-Des-&#194;mes.html&quot; title=&quot;Œil des &#226;mes&quot;&gt;Œil des &#226;mes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Enfonc&#233; dans le front d’une cr&#233;ature, permet &#224; celui qui l’a implant&#233; de voir &#224; travers les sens de cette derni&#232;re tant qu’ils sont sur le m&#234;me Plan, et consid&#232;re le porteur comme &#224; port&#233;e pour certains sorts ciblant une cr&#233;ature. Fonctionne comme un objet maudit en ce qui concerne son retrait.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Du-Loup-Arctique.html&quot; title=&quot;Bandeau du loup arctique&quot;&gt;Bandeau du loup arctique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une r&#233;sistance au froid de 10. Une fois par jour, permet de se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Loup.html&quot; title=&quot;Loup&quot;&gt;loup&lt;/a&gt; pendant 11 minutes. Une fois par jour, permet de souffler un c&#244;ne de 9 m infligeant 7d6 points de d&#233;g&#226;ts de froid.&lt;/td&gt;&lt;td&gt;32 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Contr&#244;le-Des-Illusions.html&quot; title=&quot;Bandeau de contr&#244;le des illusions&quot;&gt;Bandeau de contr&#244;le des illusions&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de modifier les param&#232;tres d&#39;une illusion non-permanente en cours. Une fois par jour, un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;elfe&lt;/a&gt; peut manifester un double illusoire (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Image-Miroir.html&quot; title=&quot;Image miroir&quot;&gt;image miroir&lt;/a&gt;&lt;/i&gt;) de six alli&#233;s maximum qu&#39;il peut d&#233;cider de contr&#244;ler s&#233;par&#233;ment.&lt;/td&gt;&lt;td&gt;40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-S&#233;duction.html&quot; title=&quot;Bandeau de s&#233;duction&quot;&gt;Bandeau de s&#233;duction&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests associ&#233;s au &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; sur les membres de son esp&#232;ce et du m&#234;me type (s’il est humano&#239;de, le bonus s’&#233;l&#232;ve &#224; +5 et s’applique sur les cr&#233;atures de son sous-type &#224; la place). Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sir-Anormal.html&quot; title=&quot;D&#233;sir anormal&quot;&gt;d&#233;sir anormal&lt;/a&gt;&lt;/i&gt; pour une dur&#233;e de 10 minutes.&lt;/td&gt;&lt;td&gt;40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-R&#233;sistance-Mentale.html&quot; title=&quot;Bandeau de r&#233;sistance mentale&quot;&gt;Bandeau de r&#233;sistance mentale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration de +2 &#224; la valeur de toutes les caract&#233;ristiques mentales (temporaire pendant les 24 premi&#232;res heures de port). Conf&#232;re 5 points de caract&#233;ristiques temporaires qui &#233;pongent les &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissements temporaires&lt;/a&gt; et les diminutions permanentes inflig&#233;es aux caract&#233;ristiques mentales.&lt;/td&gt;&lt;td&gt;64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Des-Pens&#233;es-Herm&#233;tiques.html&quot; title=&quot;Bandeau des pens&#233;es herm&#233;tiques&quot;&gt;Bandeau des pens&#233;es herm&#233;tiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d&#39;alt&#233;ration de +4 &#224; l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; (temporaire pendant les 24 premi&#232;res heures de port). Immunise le porteur contre les divinations donnant des informations sur lui (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Imp&#233;n&#233;trable.html&quot; title=&quot;Esprit imp&#233;n&#233;trable&quot;&gt;esprit imp&#233;n&#233;trable&lt;/a&gt;&lt;/i&gt;). Conf&#232;re un bonus &#233;gal au &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade mythique&lt;/a&gt; du porteur aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets mentaux. Quand il r&#233;ussit un jet de sauvegarde contre un effet mental et aux prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le porteur peut le renvoyer sur son lanceur.&lt;/td&gt;&lt;td&gt;150 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
